"""Source-disjoint scientific experience records and ungenerated Miles prompts.

This module never runs a policy, computes a reward, retokenizes a trace, or updates
weights. Eligibility is a scoped reviewer assertion tied to immutable artifacts,
not a conclusion inferred from fluent text or successful JSON validation.
"""

from __future__ import annotations

import argparse
import hashlib
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

SCHEMA_VERSION = "scientific-experience/v1"
PARTITIONS = {"development", "validation", "final_test"}
USES = {"diagnostic", "outcome_supervision", "imitation", "rollout_prompt"}
SCIENTIFIC_OUTCOMES = {"supported", "negative", "inconclusive", "contradicted"}
TRAJECTORY_KINDS = {
    "fresh_investigation",
    "continued_investigation",
    "matched_evidence_response",
    "reconstructed_investigation",
}


def canonical_hash(value: Any) -> str:
    encoded = json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(encoded.encode()).hexdigest()


def _required_string(value: Any, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a nonempty string")
    return value


def _timestamp(value: Any, name: str) -> datetime:
    value = _required_string(value, name)
    try:
        result = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"{name} must be an ISO timestamp") from exc
    if result.tzinfo is None:
        raise ValueError(f"{name} must include a timezone")
    return result


def _unique_strings(value: Any, name: str, *, nonempty: bool = True) -> list[str]:
    if not isinstance(value, list) or (nonempty and not value):
        raise ValueError(f"{name} must be an explicit {'nonempty ' if nonempty else ''}list")
    for item in value:
        _required_string(item, name)
    if len(value) != len(set(value)):
        raise ValueError(f"{name} contains duplicates")
    return value


def validate_registry(registry: dict) -> dict[str, dict]:
    """Reject leakage through either shared campaign or shared mechanism family."""
    if registry.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("unsupported registry schema_version")
    _timestamp(registry.get("frozen_at"), "frozen_at")
    _required_string(registry.get("frozen_by"), "frozen_by")
    payload = {k: v for k, v in registry.items() if k != "registry_sha256"}
    if registry.get("registry_sha256") != canonical_hash(payload):
        raise ValueError("registry digest mismatch; freeze a new version instead of editing")
    sources = registry.get("sources")
    if not isinstance(sources, list) or not sources:
        raise ValueError("registry requires source-level assignments before example derivation")
    index: dict[str, dict] = {}
    assignments: dict[tuple[str, str], str] = {}
    for source in sources:
        source_id = _required_string(source.get("source_id"), "source_id")
        if source_id in index:
            raise ValueError(f"duplicate source_id: {source_id}")
        partition = source.get("partition")
        if partition not in PARTITIONS:
            raise ValueError(f"invalid source partition: {partition}")
        for field in ("campaign_id", "mechanism_family"):
            value = _required_string(source.get(field), field)
            key = field, value.strip().casefold()
            if key in assignments and assignments[key] != partition:
                raise ValueError(f"{field} crosses source partitions: {value}")
            assignments[key] = partition
        for field in ("origin", "source_locator", "rights_status", "exposure_status"):
            _required_string(source.get(field), field)
        if source["exposure_status"] == "development_exposed" and partition != "development":
            raise ValueError(f"development-exposed source cannot be protected: {source_id}")
        index[source_id] = source
    return index


def freeze_registry(sources: list[dict], *, frozen_by: str, frozen_at: str | None = None) -> dict:
    registry = {
        "schema_version": SCHEMA_VERSION,
        "frozen_at": frozen_at or datetime.now(UTC).isoformat(),
        "frozen_by": frozen_by,
        "sources": sources,
    }
    registry["registry_sha256"] = canonical_hash(registry)
    validate_registry(registry)
    return registry


def _artifact_path(root: Path, relative: Any) -> Path:
    relative = _required_string(relative, "artifact path")
    if Path(relative).is_absolute():
        raise ValueError("artifact paths must be relative to the explicit evidence root")
    path = (root / relative).resolve()
    if not path.is_relative_to(root.resolve()) or not path.is_file():
        raise ValueError(f"artifact missing or outside evidence root: {relative}")
    return path


def _artifact_index(artifacts: Any, root: Path, *, add_hashes: bool) -> dict[str, dict]:
    if not isinstance(artifacts, list) or not artifacts:
        raise ValueError("original artifact inventory is required")
    index = {}
    for artifact in artifacts:
        aid = _required_string(artifact.get("artifact_id"), "artifact_id")
        if aid in index:
            raise ValueError(f"duplicate artifact_id: {aid}")
        if artifact.get("visibility") not in {"investigator", "reviewer", "protected"}:
            raise ValueError(f"explicit artifact visibility required: {aid}")
        path = _artifact_path(root, artifact.get("path"))
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if add_hashes and "sha256" not in artifact:
            artifact["sha256"] = actual
        if artifact.get("sha256") != actual:
            raise ValueError(f"artifact digest mismatch: {aid}")
        index[aid] = artifact
    return index


def _references(value: Any, name: str, artifacts: dict, *, nonempty: bool = True) -> list[str]:
    refs = _unique_strings(value, name, nonempty=nonempty)
    if any(ref not in artifacts for ref in refs):
        raise ValueError(f"{name} has unresolved artifact references")
    return refs


def validate_record(record: dict, registry: dict, *, evidence_root: Path | str) -> dict:
    sources = validate_registry(registry)
    if record.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("unsupported record schema_version")
    if record.get("registry_sha256") != registry["registry_sha256"]:
        raise ValueError("record is not bound to this frozen source registry")
    payload = {k: v for k, v in record.items() if k != "record_sha256"}
    if record.get("record_sha256") != canonical_hash(payload):
        raise ValueError("record digest mismatch")
    derived_at = _timestamp(record.get("derived_at"), "derived_at")
    if derived_at < _timestamp(registry["frozen_at"], "frozen_at"):
        raise ValueError("source partitions must be frozen before example derivation")
    _required_string(record.get("episode_id"), "episode_id")
    source_ids = _unique_strings(record.get("source_ids"), "source_ids")
    if any(sid not in sources for sid in source_ids):
        raise ValueError("episode has an unregistered source")
    partitions = {sources[sid]["partition"] for sid in source_ids}
    if len(partitions) != 1 or record.get("partition") not in partitions:
        raise ValueError("an episode cannot mix source partitions")
    if record.get("scientific_status") != "complete":
        raise ValueError("only complete scientific episodes can become experience records")
    if record.get("outcome_kind") not in SCIENTIFIC_OUTCOMES:
        raise ValueError("infrastructure failure or censored execution is not a scientific outcome")
    if record.get("trajectory_kind") not in TRAJECTORY_KINDS:
        raise ValueError(
            "trajectory_kind must distinguish fresh, continued and owner-created records"
        )
    model = record.get("policy", {})
    for field in ("model_id", "provider", "precision", "checkpoint_identity"):
        _required_string(model.get(field), f"policy.{field}")
    if not isinstance(model.get("reasoning_settings"), dict):
        raise TypeError("policy.reasoning_settings must be explicit, including unknown settings")
    if not isinstance(record.get("assistance"), list):
        raise TypeError("assistance must be explicit, including an empty list")
    if not isinstance(record.get("resources"), dict):
        raise TypeError("resources must record measured usage or explicitly unknown values")
    artifacts = _artifact_index(record.get("artifacts"), Path(evidence_root), add_hashes=False)
    for field in ("original_events", "executable_artifacts", "outcome_reviews"):
        _references(record.get(field), field, artifacts)
    # Only public identity metadata is inspected, never reasoning text.
    # A resumed session with a different policy belongs in a separate linked record.
    for ref in record["original_events"]:
        artifact = artifacts[ref]
        if (
            artifact.get("format") == "pi_session_jsonl"
            or Path(artifact["path"]).suffix == ".jsonl"
        ):
            path = _artifact_path(Path(evidence_root), artifact["path"])
            captured_ids = set()
            captured_providers = set()
            with path.open() as stream:
                for line in stream:
                    if not line.strip():
                        continue
                    event = json.loads(line)
                    if event.get("type") == "model_change":
                        captured_ids.add(event.get("modelId"))
                        if event.get("provider"):
                            captured_providers.add(event["provider"])
                    message = event.get("message", {})
                    if message.get("role") == "assistant":
                        if message.get("model"):
                            captured_ids.add(message["model"])
                        if message.get("provider"):
                            captured_providers.add(message["provider"])
            declared_native = artifact.get("format") == "pi_session_jsonl"
            if (captured_ids or declared_native) and captured_ids != {model["model_id"]}:
                raise ValueError("Pi model-boundary receipts do not match the single-policy record")
            if captured_providers and captured_providers != {model["provider"]}:
                raise ValueError(
                    "Pi provider-boundary receipts do not match the single-policy record"
                )
    segments = record.get("policy_segments")
    if not isinstance(segments, list) or not segments:
        raise ValueError("explicit policy segment receipts are required")
    for segment in segments:
        if segment.get("model_id") != model["model_id"]:
            raise ValueError("mixed-model trajectories must be segmented into separate records")
        refs = _references(segment.get("event_refs"), "policy segment events", artifacts)
        if not set(refs) <= set(record["original_events"]):
            raise ValueError("policy segment must bind original event artifacts")
    supplied = _references(
        record.get("supplied_model_artifacts"),
        "supplied_model_artifacts",
        artifacts,
        nonempty=False,
    )
    adopted_hashes = {artifacts[ref]["sha256"] for ref in record["executable_artifacts"]}
    reused = {ref for ref in supplied if artifacts[ref]["sha256"] in adopted_hashes}
    attributed = set()
    for assistance in record["assistance"]:
        if not isinstance(assistance, dict):
            raise TypeError("assistance entries must identify kind and artifact_refs")
        _required_string(assistance.get("kind"), "assistance.kind")
        attributed.update(
            _references(assistance.get("artifact_refs"), "assistance artifacts", artifacts)
        )
    if not reused <= attributed:
        raise ValueError("adopted supplied-model bytes require explicit assistance attribution")
    initial = _references(record.get("initial_information"), "initial_information", artifacts)
    if any(artifacts[ref]["visibility"] != "investigator" for ref in initial):
        raise ValueError("initial information includes privileged material")
    releases = record.get("evidence_releases")
    if not isinstance(releases, list):
        raise TypeError("evidence_releases must preserve an explicit ordered release history")
    seen_evidence: set[str] = set()
    seen_release_ids: set[str] = set()
    last_time: datetime | None = None
    for release in releases:
        release_id = _required_string(release.get("release_id"), "release_id")
        if release_id in seen_release_ids:
            raise ValueError("duplicate release_id")
        seen_release_ids.add(release_id)
        when = _timestamp(release.get("released_at"), "released_at")
        if when > derived_at:
            raise ValueError("experience cannot include an evidence release after derivation")
        if last_time is not None and when < last_time:
            raise ValueError("release chronology runs backwards")
        last_time = when
        refs = _references(release.get("artifact_refs"), "release artifacts", artifacts)
        if any(artifacts[ref]["visibility"] != "investigator" for ref in refs):
            raise ValueError("released evidence includes privileged evaluator artifacts")
        eids = _unique_strings(release.get("evidence_ids"), "evidence_ids")
        if seen_evidence.intersection(eids):
            raise ValueError("duplicated observations are not new acquired evidence")
        seen_evidence.update(eids)
    branches = record.get("branches")
    if not isinstance(branches, list) or not branches:
        raise ValueError("branch ancestry is required, including the root branch")
    seen_branches: set[str] = set()
    for branch in branches:
        bid = _required_string(branch.get("branch_id"), "branch_id")
        if bid in seen_branches or branch.get("parent_branch_id") not in seen_branches | {None}:
            raise ValueError("branch ancestry is duplicated, cyclic, or unresolved")
        if seen_branches and branch.get("parent_branch_id") is None:
            raise ValueError("episode must have one root branch")
        seen_branches.add(bid)
    commitments = record.get("commitments")
    if not isinstance(commitments, list) or not commitments:
        raise ValueError("prospective predictions or decision commitments are required")
    for commitment in commitments:
        when = _timestamp(commitment.get("committed_at"), "committed_at")
        if when > derived_at:
            raise ValueError("experience cannot include a commitment after derivation")
        if commitment.get("branch_id") not in seen_branches:
            raise ValueError("commitment refers to unknown branch")
        _references(commitment.get("artifact_refs"), "commitment artifacts", artifacts)
        cutoff = _unique_strings(commitment.get("release_cutoff"), "release_cutoff", nonempty=False)
        available = {
            r["release_id"] for r in releases if _timestamp(r["released_at"], "released_at") <= when
        }
        if not set(cutoff) <= available:
            raise ValueError("commitment contains evidence unavailable at its timestamp")
    eligibility = record.get("eligibility", {})
    allowed = _unique_strings(eligibility.get("allowed_uses"), "allowed_uses", nonempty=False)
    if not set(allowed) <= USES:
        raise ValueError("unknown training use")
    for field in ("reviewer", "rationale", "rights_basis"):
        _required_string(eligibility.get(field), f"eligibility.{field}")
    _references(eligibility.get("review_refs"), "eligibility.review_refs", artifacts)
    if eligibility.get("independent_review") is not True:
        raise ValueError("independent scientific review must be explicit")
    if record["outcome_kind"] != "supported" and "imitation" in allowed:
        raise ValueError("negative or wrong outcomes are not automatically imitation targets")
    if record["trajectory_kind"] in {
        "matched_evidence_response",
        "reconstructed_investigation",
    } and set(allowed) & {"imitation", "rollout_prompt"}:
        raise ValueError("owner-created evidence controls or reconstructions are diagnostic only")
    if (
        any(sources[s]["rights_status"] != "cleared_for_declared_use" for s in source_ids)
        and allowed
    ):
        raise ValueError("uncleared source rights prohibit training eligibility")
    if record["partition"] != "development" and allowed:
        raise ValueError("validation and final-test records are never training eligible")
    if record.get("native_training_tokens") is not None:
        raise ValueError("native token records require a separate on-policy capture interface")
    return {
        "valid": True,
        "episode_id": record["episode_id"],
        "partition": record["partition"],
        "eligible_uses": allowed,
        "semantic_support": "reviewer_attestation_not_recomputed",
        "on_policy_token_record": False,
    }


def export_record(
    descriptor: dict, registry: dict, *, evidence_root: Path | str, derived_at: str | None = None
) -> dict:
    """Hash declared original artifacts; never mutate the originals or discover files."""
    record = json.loads(json.dumps(descriptor, allow_nan=False))
    sources = validate_registry(registry)
    if any(sid not in sources for sid in record.get("source_ids", [])):
        raise ValueError("episode has an unregistered source")
    partitions = {sources[sid]["partition"] for sid in record.get("source_ids", [])}
    if len(partitions) != 1:
        raise ValueError("episode source IDs must resolve to one partition")
    record.update(
        schema_version=SCHEMA_VERSION,
        registry_sha256=registry["registry_sha256"],
        derived_at=derived_at or datetime.now(UTC).isoformat(),
        partition=partitions.pop(),
    )
    _artifact_index(record.get("artifacts"), Path(evidence_root), add_hashes=True)
    record.pop("record_sha256", None)
    record["record_sha256"] = canonical_hash(record)
    validate_record(record, registry, evidence_root=evidence_root)
    return record


def rollout_prompt_row(
    record: dict, registry: dict, *, evidence_root: Path | str, prompt_artifact_id: str
) -> dict:
    """Return initial information for a *new* rollout, with no historical response.

    The reviewer must designate and review the exact prompt artifact. Paths,
    outcome reviews and historical solutions stay in the owner-side record.
    """
    validate_record(record, registry, evidence_root=evidence_root)
    if record["partition"] != "development":
        raise ValueError("protected source cannot become a training prompt")
    if "rollout_prompt" not in record["eligibility"]["allowed_uses"]:
        raise ValueError("record lacks reviewed rollout-prompt eligibility")
    if prompt_artifact_id not in record["initial_information"]:
        raise ValueError("rollout prompt must be original initial information")
    artifact = next(a for a in record["artifacts"] if a["artifact_id"] == prompt_artifact_id)
    prompt = json.loads(_artifact_path(Path(evidence_root), artifact["path"]).read_text())
    if isinstance(prompt, dict):
        if set(prompt) != {"prompt"}:
            raise ValueError("prompt artifact must contain only the reviewed initial prompt")
        prompt = prompt["prompt"]
    if isinstance(prompt, str):
        _required_string(prompt, "prompt")
    elif isinstance(prompt, list) and prompt:
        for message in prompt:
            if not isinstance(message, dict) or set(message) != {"role", "content"}:
                raise ValueError("initial prompt messages require exactly role and content")
            if message["role"] not in {"system", "user"}:
                raise ValueError("initial rollout prompt must not include a historical solution")
            _required_string(message["content"], "message content")
    else:
        raise ValueError("initial prompt must be text or an initial message list")
    return {
        "prompt": prompt,
        "metadata": {
            "scientific_experience": {
                "schema_version": SCHEMA_VERSION,
                "record_sha256": record["record_sha256"],
                "registry_sha256": registry["registry_sha256"],
                "episode_id": record["episode_id"],
                "partition": record["partition"],
                "prompt_sha256": artifact["sha256"],
                "purpose": "new_interactive_rollout_initial_state",
                "requires_environment_reset": True,
            }
        },
    }


def to_miles_prompt_sample(row: dict):
    """Build the real Miles Sample; importing Miles is optional until this call.

    Sample stays PENDING, with empty tokens, no response, reward, loss mask, or
    log probabilities. This is input-interface verification, not a training step.
    """
    if set(row) != {"prompt", "metadata"}:
        raise ValueError("Miles prompt rows must not include generated data or rewards")
    metadata = row.get("metadata", {}).get("scientific_experience", {})
    if metadata.get("partition") != "development":
        raise ValueError("Miles training prompt requires the development partition")
    from miles.utils.types import Sample

    return Sample(prompt=row["prompt"], metadata=row["metadata"])


def _write_new(path: Path, value: Any, *, jsonl: bool = False) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("x") as handle:
        handle.write(json.dumps(value, indent=None if jsonl else 2, allow_nan=False) + "\n")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    freeze = sub.add_parser("freeze")
    freeze.add_argument("--sources", type=Path, required=True)
    freeze.add_argument("--frozen-by", required=True)
    freeze.add_argument("--output", type=Path, required=True)
    for name in ("export", "validate", "prompt"):
        cmd = sub.add_parser(name)
        cmd.add_argument("--registry", type=Path, required=True)
        cmd.add_argument("--record", type=Path, required=True)
        cmd.add_argument("--evidence-root", type=Path, required=True)
        if name != "validate":
            cmd.add_argument("--output", type=Path, required=True)
        if name == "prompt":
            cmd.add_argument("--prompt-artifact-id", required=True)
    args = parser.parse_args(argv)
    if args.command == "freeze":
        result = freeze_registry(json.loads(args.sources.read_text()), frozen_by=args.frozen_by)
        _write_new(args.output, result)
    else:
        registry = json.loads(args.registry.read_text())
        record = json.loads(args.record.read_text())
        if args.command == "export":
            result = export_record(record, registry, evidence_root=args.evidence_root)
            _write_new(args.output, result)
        elif args.command == "prompt":
            result = rollout_prompt_row(
                record,
                registry,
                evidence_root=args.evidence_root,
                prompt_artifact_id=args.prompt_artifact_id,
            )
            _write_new(args.output, result, jsonl=True)
        else:
            result = validate_record(record, registry, evidence_root=args.evidence_root)
        print(
            json.dumps(
                {
                    k: v
                    for k, v in result.items()
                    if k in {"valid", "episode_id", "partition", "eligible_uses", "record_sha256"}
                }
            )
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
